      title?: string;
      notes?: string | null;
      leaderNotes?: string | null;
      meetPlace?: string | null;
      opponent?: string | null;
      /** @enum {string|null} */
      homeAway?: "home" | "away" | "neutral" | null;
      competition?: string | null;
